/** static void SetFlashScanlineEffectWindowBoundary(u16 *dest, u32 y, s32 left, s32 right) */
export function SetFlashScanlineEffectWindowBoundary(dest: any, y: any, left: any, right: any): any {
  if (y <= 160)
      {
          if (left < 0)
              left = 0;
          if (left > 255)
              left = 255;
          if (right < 0)
              right = 0;
          if (right > 255)
              right = 255;
          dest[y] = (left << 8) | right;
      }
}

/** static void SetFlashScanlineEffectWindowBoundaries(u16 *dest, s32 centerX, s32 centerY, s32 radius) */
export function SetFlashScanlineEffectWindowBoundaries(dest: any, centerX: any, centerY: any, radius: any): any {
  let r: any = radius;
      let v2: any = radius;
      let v3: any = 0;
      while (r >= v3)
      {
          SetFlashScanlineEffectWindowBoundary(dest, centerY - v3, centerX - r, centerX + r);
          SetFlashScanlineEffectWindowBoundary(dest, centerY + v3, centerX - r, centerX + r);
          SetFlashScanlineEffectWindowBoundary(dest, centerY - r, centerX - v3, centerX + v3);
          SetFlashScanlineEffectWindowBoundary(dest, centerY + r, centerX - v3, centerX + v3);
          v2 -= (v3 * 2) - 1;
          v3++;
          if (v2 < 0)
          {
              v2 += 2 * (r - 1);
              r--;
          }
      }
}

/** static void SetOrbFlashScanlineEffectWindowBoundary(u16 *dest, u32 y, s32 left, s32 right) */
export function SetOrbFlashScanlineEffectWindowBoundary(dest: any, y: any, left: any, right: any): any {
  if (y <= 160)
      {
          if (left < 0)
              left = 0;
          if (left > 240)
              left = 240;
          if (right < 0)
              right = 0;
          if (right > 240)
              right = 240;
          dest[y] = (left << 8) | right;
      }
}

/** static void SetOrbFlashScanlineEffectWindowBoundaries(u16 *dest, s32 centerX, s32 centerY, s32 radius) */
export function SetOrbFlashScanlineEffectWindowBoundaries(dest: any, centerX: any, centerY: any, radius: any): any {
  let r: any = radius;
      let v2: any = radius;
      let v3: any = 0;
      while (r >= v3)
      {
          SetOrbFlashScanlineEffectWindowBoundary(dest, centerY - v3, centerX - r, centerX + r);
          SetOrbFlashScanlineEffectWindowBoundary(dest, centerY + v3, centerX - r, centerX + r);
          SetOrbFlashScanlineEffectWindowBoundary(dest, centerY - r, centerX - v3, centerX + v3);
          SetOrbFlashScanlineEffectWindowBoundary(dest, centerY + r, centerX - v3, centerX + v3);
          v2 -= (v3 * 2) - 1;
          v3++;
          if (v2 < 0)
          {
              v2 += 2 * (r - 1);
              r--;
          }
      }
}

/** static void UpdateFlashLevelEffect(u8 taskId) */
export function UpdateFlashLevelEffect(taskId: any): any {
  let data: any = gTasks[taskId].data;

      switch (tState)
      {
      case 0:
          SetFlashScanlineEffectWindowBoundaries(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX, tFlashCenterY, tCurFlashRadius);
          tState = 1;
          break;
      case 1:
          SetFlashScanlineEffectWindowBoundaries(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX, tFlashCenterY, tCurFlashRadius);
          tState = 0;
          tCurFlashRadius += tFlashRadiusDelta;
          if (tCurFlashRadius > tDestFlashRadius)
          {
              if (tClearScanlineEffect == 1)
              {
                  ScanlineEffect_Stop();
                  tState = 2;
              }
              else
              {
                  DestroyTask(taskId);
              }
          }
          break;
      case 2:
          ScanlineEffect_Clear();
          DestroyTask(taskId);
          break;
      }
}

