export function WriteBattlePyramidViewScanlineEffectBuffer(): any {
  SetFlashScanlineEffectWindowBoundaries(gScanlineEffectRegBuffers[0][0], DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, gSaveBlock2Ptr.frontier.pyramidLightRadius);
      CpuFastSet(gScanlineEffectRegBuffers[0],gScanlineEffectRegBuffers[1], 480);
}

/** static void Task_SpinEnterWarp(u8 taskId) */
export function Task_SpinEnterWarp(taskId: any): any {
  switch (gTasks[taskId].tState)
      {
      case 0:
          FreezeObjectEvents();
          LockPlayerFieldControls();
          DoPlayerSpinEntrance();
          gTasks[taskId].tState++;
          break;
      case 1:
          if (WaitForWeatherFadeIn() && IsPlayerSpinEntranceActive() != TRUE)
          {
              UnfreezeObjectEvents();
              UnlockPlayerFieldControls();
              DestroyTask(taskId);
          }
          break;
      }
}

/** static void Task_SpinExitWarp(u8 taskId) */
export function Task_SpinExitWarp(taskId: any): any {
  let task: any =gTasks[taskId];

      switch (task.tState)
      {
      case 0:
          FreezeObjectEvents();
          LockPlayerFieldControls();
          PlaySE(SE_WARP_IN);
          DoPlayerSpinExit();
          task.tState++;
          break;
      case 1:
          if (!IsPlayerSpinExitActive())
          {
              WarpFadeOutScreen();
              task.tState++;
          }
          break;
      case 2:
          if (!PaletteFadeActive() && BGMusicStopped())
              task.tState++;
          break;
      case 3:
          WarpIntoMap();
          SetMainCallback2(CB2_LoadMap);
          DestroyTask(taskId);
          break;
      }
}

